372	    /**
373	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
374	     * contained in {@code value}. Reading the digits right to left, every second one is
375	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
376	     * digits are summed, and the check digit is the amount that must be added to that sum to
377	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
378	     * the digit is taken over exactly the digits the string carries.
379	     */
380	    private static int luhnCheckDigit(String value) {
381	        int sum = 0;
382	        boolean doubling = true;
383	        for (int i = value.length() - 1; i >= 0; i--) {
384	            char c = value.charAt(i);
385	            if (c < '0' || c > '9') {
386	                continue;
387	            }
388	            int digit = c - '0';
389	            if (doubling) {
390	                digit *= 2;
391	                if (digit > 9) {
392	                    digit -= 9;
393	                }
394	            }
395	            sum += digit;
396	            doubling = !doubling;
397	        }
398	        return (10 - (sum % 10)) % 10;
399	    }
