424	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
425	     * known region). Locality is read from the region-and-hash identity so it never re-derives
426	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
427	     */
428	    public String getLocality() {
429	        if (this.customerCode == null) {
430	            return UNKNOWN_REGION;
431	        }
432	        int dash = this.customerCode.indexOf('-');
433	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
434	    }
435	
436	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
437	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
438	        "NSW", "Australia/Sydney",
439	        "VIC", "Australia/Melbourne",
440	        "QLD", "Australia/Brisbane");
441	
442	    /**
443	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
444	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
445	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
446	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
447	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
448	     */
449	    public String getTimezone() {
450	        return REGION_TIMEZONE.get(getLocality());
451	    }
452	
453	    /**
454	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
455	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. TIER is
456	     * {@code 'PREMIUM'} when {@linkplain #getMembershipLevel() membershipLevel} is 3 or more,
457	     * otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's
458	     * {@linkplain #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
459	     * {@code 'REGIONAL'}. It reads the locality against the shared region table so it never
460	     * re-derives a region of its own.
461	     */
462	    public String getOwnerSegment() {
463	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
464	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
465	        return tier + "_" + area;
466	    }
467	
468	    /**
469	     * The region derived from this owner's postcode alone: the region whose fixed
470	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
471	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
472	     * component built into the owner's customer code at creation and, through it, the source of the
473	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
474	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
475	     */
476	    public String getRegion() {
477	        return regionOfPostcode(this.postcode);
478	    }
479	
480	    /**
481	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
482	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
483	     * no known range.
484	     */
485	    private static String regionOfPostcode(String postcode) {
486	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
487	            return null;
488	        }
489	        int value = Integer.parseInt(postcode);
490	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
491	            int[] range = entry.getValue();
492	            if (value >= range[0] && value <= range[1]) {
493	                return entry.getKey();
494	            }
495	        }
496	        return null;
497	    }
498	
499	    /**
500	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
501	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
502	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
503	     */
504	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
505	        "NSW", new int[] {2000, 2099},
506	        "VIC", new int[] {3000, 3099},
507	        "QLD", new int[] {4000, 4099});
508	
509	    /**
510	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
511	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
512	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
513	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
514	     * city with no known region accepts any 4-digit postcode.
515	     */
516	    public boolean isPostcodeValid() {
517	        if (this.postcode == null) {
518	            return true;
519	        }
520	        if (!this.postcode.matches("[0-9]{4}")) {
521	            return false;
522	        }
523	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
524	        if (range == null) {
525	            return true;
526	        }
527	        int value = Integer.parseInt(this.postcode);
528	        return value >= range[0] && value <= range[1];
529	    }
530	
531	    /**
532	     * The national (subscriber) digit count required by each known country calling code, keyed by
533	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
534	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
535	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
536	     * re-derived elsewhere.
537	     */
538	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
539	        "1", 10,
540	        "61", 9);
541	
542	    /**
543	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
544	     * E.164 digit string, choosing the longest matching code known to
545	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
546	     * country code. This is the single place a country code is read from an E.164 number, so every
547	     * rule keyed by that code shares one derivation.
548	     */
549	    private static String countryCodeOf(String e164Digits) {
550	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
551	            .filter(e164Digits::startsWith)
552	            .max(Comparator.comparingInt(String::length))
553	            .orElse(null);
554	    }
555	
556	    /**
557	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
558	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
559	     * known code wins; a number whose country code is not recognised passes this check (its length is
560	     * then governed only by the general E.164 bound), while a recognised code must be followed by
561	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
562	     */
563	    public static boolean hasValidNationalLength(String e164Digits) {
564	        String countryCode = countryCodeOf(e164Digits);
565	        if (countryCode == null) {
566	            return true;
567	        }
568	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
569	    }
570	
571	    /**
572	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
573	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
574	     * gain 3 when the owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one
575	     * elapsed fiscal year. The email, namesake and household factors are available on creation; the
576	     * tenure factor is reached only once at least one fiscal-year boundary has passed.
577	     */
578	    public Integer getMembershipPoints() {
579	        int points = 0;
580	        if (hasEmail()) {
581	            points += 2;
582	        }
583	        if (hasNoNamesakes()) {
584	            points += 1;
585	        }
586	        if (hasLargeHousehold()) {
587	            points += 2;
588	        }
589	        if (hasQualifyingTenure()) {
590	            points += 3;
591	        }
592	        return points;
593	    }
594	
595	    /**
596	     * The owner's membership level, a number from 1 to 4. For an owner created through the
597	     * creation pipeline this is the value assigned and stored at creation time; an owner that
598	     * carries no assigned level (e.g. seed data, or an owner not created through that pipeline)
599	     * reports its {@linkplain #getBaseMembershipLevel() base level} derived from its
600	     * membershipPoints. This is the single value read by the API for an owner's membership level.
601	     */
602	    public Integer getMembershipLevel() {
603	        return this.membershipLevel != null ? this.membershipLevel : getBaseMembershipLevel();
604	    }
605	
606	    public void setMembershipLevel(Integer membershipLevel) {
607	        this.membershipLevel = membershipLevel;
608	    }
609	
610	    /**
611	     * The owner's base membership level, a number from 1 to 4 derived directly from
612	     * {@linkplain #getMembershipPoints() membershipPoints}: level 1 for 0-1 points, level 2 for 2-3,
613	     * level 3 for 4-5, and level 4 for 6 or more. This is the level the creation pipeline starts
614	     * from when it assigns the owner's stored {@linkplain #getMembershipLevel() membershipLevel}.
615	     */
616	    public Integer getBaseMembershipLevel() {
617	        int points = getMembershipPoints();
618	        if (points >= 6) {
619	            return 4;
620	        }
621	        if (points >= 4) {
622	            return 3;
623	        }
624	        if (points >= 2) {
625	            return 2;
626	        }
627	        return 1;
628	    }
629	
630	    /**
631	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
632	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
633	     * known, is treated as not a large household.
634	     */
635	    private boolean hasLargeHousehold() {
636	        return this.householdSize != null && this.householdSize >= 3;
637	    }
638	
639	    /**
640	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
641	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
642	     * email presence so the check is never re-derived elsewhere.
643	     */
644	    private boolean hasEmail() {
645	        return this.email != null && !this.email.isEmpty();
646	    }
647	
648	    /**
649	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
650	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
651	     * not known, is treated as not unique.
652	     */
653	    private boolean hasNoNamesakes() {
654	        return this.namesakeCount != null && this.namesakeCount == 0;
655	    }
656	
657	    /**
658	     * Whether this owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one elapsed
659	     * fiscal year. A newly created owner (zero elapsed fiscal years) does not qualify; the threshold
660	     * is crossed only once at least one fiscal-year boundary has passed since registration.
661	     */
662	    private boolean hasQualifyingTenure() {
663	        return this.getTenureFiscalYears() >= 1;
664	    }
665	
666	    /**
667	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
668	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
669	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
670	     * created owner has zero tenure). Never negative.
671	     */
672	    public long getTenureFiscalYears() {
673	        if (this.registrationDate == null) {
674	            return 0;
675	        }
676	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
677	    }
678	
679	    /**
680	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
681	     * otherwise {@code 'PHONE'}.
682	     */
683	    public String getContactPreference() {
684	        return hasEmail() ? "EMAIL" : "PHONE";
685	    }
686	
687	    /**
688	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
689	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
690	     * the national digits grouped into threes from the left separated by spaces,
691	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
692	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
693	     * E.164 form, or carries no known country code.
694	     */
695	    public String getTelephoneDisplay() {
696	        if (this.telephone == null || !this.telephone.startsWith("+")) {
697	            return this.telephone;
698	        }
699	        String digits = this.telephone.substring(1);
700	        String countryCode = countryCodeOf(digits);
701	        if (countryCode == null) {
702	            return this.telephone;
703	        }
704	        String national = digits.substring(countryCode.length());
705	        StringBuilder groups = new StringBuilder();
706	        for (int i = 0; i < national.length(); i += 3) {
707	            if (groups.length() > 0) {
708	                groups.append(' ');
709	            }
710	            groups.append(national, i, Math.min(i + 3, national.length()));
711	        }
712	        return "+" + countryCode + " " + groups;
713	    }
714	
715	    /**
716	     * The owner's identity key: the single derived value used for duplicate detection. It is the
717	     * lower-case hex SHA-256 (64 characters) of the normalized (E.164) telephone, the email
718	     * (already lower-cased, or the empty string when absent) and the {@linkplain #soundex(String)
719	     * soundex} of the lastName, joined with {@code '|'} before hashing, e.g. the digest of
720	     * {@code '+61412345678|jane@example.test|J500'}. Two owners are duplicates, and the second is
721	     * rejected with {@code 409}, only when their whole identity keys are equal.
722	     */
723	    public String getIdentityKey() {
724	        String telephonePart = this.telephone == null ? "" : this.telephone;
725	        String emailPart = this.email == null ? "" : this.email;
726	        String soundexPart = soundex(this.getLastName());
727	        return HashUtils.sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
728	    }
729	
730	    /**
731	     * The American Soundex code of {@code name}: its first letter followed by three digits encoding
732	     * the remaining consonant sounds ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2};
733	     * {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w,y}
734	     * are not coded). Adjacent letters with the same code, and same-coded letters separated only by
735	     * {@code h} or {@code w}, contribute a single digit; a vowel between two same-coded letters
736	     * keeps both. The result is right-padded with zeros and truncated to four characters. Non-letters
737	     * are ignored, and a {@code null} or letter-free name yields the empty string. Used to build the
738	     * owner's {@link #getIdentityKey() identity key} and to group households by surname sound.
739	     */
740	    public static String soundex(String name) {
741	        if (name == null) {
742	            return "";
743	        }
744	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
745	        if (letters.isEmpty()) {
746	            return "";
747	        }
748	        StringBuilder code = new StringBuilder();
749	        code.append(letters.charAt(0));
750	        char previous = soundexDigit(letters.charAt(0));
751	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
752	            char c = letters.charAt(i);
753	            char digit = soundexDigit(c);
754	            if (digit != '0' && digit != previous) {
755	                code.append(digit);
756	            }
757	            if (c != 'H' && c != 'W') {
758	                previous = digit;
759	            }
760	        }
761	        while (code.length() < 4) {
762	            code.append('0');
763	        }
764	        return code.toString();
765	    }
766	
767	    /**
768	     * The Soundex digit for a single upper-case letter (see {@link #soundex(String)}), or
769	     * {@code '0'} for a letter that is not coded (a vowel, or {@code h}, {@code w} or {@code y}).
770	     */
771	    private static char soundexDigit(char c) {
772	        switch (c) {
773	            case 'B': case 'F': case 'P': case 'V':
774	                return '1';
775	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
776	                return '2';
777	            case 'D': case 'T':
778	                return '3';
779	            case 'L':
780	                return '4';
781	            case 'M': case 'N':
782	                return '5';
783	            case 'R':
784	                return '6';
785	            default:
786	                return '0';
787	        }
788	    }
789	
790	    protected Set<Pet> getPetsInternal() {
791	        if (this.pets == null) {
792	            this.pets = new HashSet<>();
793	        }
794	        return this.pets;
795	    }
796	
797	    protected void setPetsInternal(Set<Pet> pets) {
798	        this.pets = pets;
799	    }
800	
801	    public List<Pet> getPets() {
802	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
803	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
804	        return Collections.unmodifiableList(sortedPets);
805	    }
806	
807	    public void setPets(List<Pet> pets) {
808	        this.pets = new HashSet<>(pets);
809	    }
810	
811	    public void addPet(Pet pet) {
812	        getPetsInternal().add(pet);
813	        pet.setOwner(this);
814	    }
815	
816	    /**
817	     * Return the Pet with the given name, or null if none found for this Owner.
818	     *
819	     * @param name to test
820	     * @return true if pet name is already in use
821	     */
822	    public Pet getPet(String name) {
823	        return getPet(name, false);
824	    }
825	
826	    /**
827	     * Return the Pet with the given name, or null if none found for this Owner.
828	     *
829	     * @param name to test
830	     * @return true if pet name is already in use
831	     */
832	    public Pet getPet(String name, boolean ignoreNew) {
833	        name = name.toLowerCase();
834	        for (Pet pet : getPetsInternal()) {
835	            if (!ignoreNew || !pet.isNew()) {
836	                String compName = pet.getName();
837	                compName = compName.toLowerCase();
838	                if (compName.equals(name)) {
839	                    return pet;
840	                }
841	            }
842	        }
843	        return null;
844	    }
845	
846	    public Pet getPet(Integer petId) {
847	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
848	    }
849	
850	    @Override
851	    public String toString() {
852	        return new ToStringCreator(this)
853	
854	            .append("id", this.getId())
855	            .append("new", this.isNew())
856	            .append("lastName", this.getLastName())
857	            .append("firstName", this.getFirstName())
858	            .append("address", this.address)
859	            .append("city", this.city)
860	            .append("telephone", this.telephone)
861	            .append("email", this.email)
862	            .toString();
863	    }
864	}
