 */
private int householdSize(String householdId) {
    if (householdId == null) {
        return 1;
    }
    long existing = this.clinicService.findAllOwners().stream()
        .filter(other -> householdId.equals(other.getHouseholdId()))
        .count();
    return (int) existing + 1;
}

