        .map(Owner::getMemberId)
        .filter(Objects::nonNull)
        .collect(Collectors.toSet());

    if (!existingIds.contains(base)) {
        return base;
    }
    int n = 2;
    while (existingIds.contains(base + "-" + n)) {
        n++;
    }
    return base + "-" + n;
}

